from dataclasses import dataclass

T = TypeVar('T')

@dataclass(frozen=True)
class Some(Generic[T]):
    value: T

class _None:
    def __repr__(self):
        return "Nothing"

Nothing = _None()

Option = Union[Some[T], _None]

def safe_divide(dividend: float, divisor: float) -> Option[float]:
    if divisor == 0:
        return Nothing
    return Some(dividend / divisor)

def main():
    # Test 1: Successful division
    result1 = safe_divide(10, 2)
    if isinstance(result1, Some):
        print(f"Result: {result1.value}")
    else:
        print("Error: Division by zero")

    # Test 2: Division by zero
    result2 = safe_divide(10, 0)
    if isinstance(result2, Some):
        print(f"Result: {result2.value}")
    else:
        print("Error: Division by zero")

if __name__ == "__main__":
