from typing import TypeVar, Generic, Union

T = TypeVar('T')
E = TypeVar('E')

class Ok(Generic[T]):
    def __init__(self, value: T):
        self._value = value

    def is_ok(self) -> bool:
        return True

    def is_err(self) -> bool:
        return False

    def unwrap(self) -> T:
        return self._value

    def __repr__(self) -> str:
        return f"Ok({repr(self._value)})"

class Err(Generic[E]):
    def __init__(self, message: E):
        self._message = message

    def is_ok(self) -> bool:
        return False

    def is_err(self) -> bool:
        return True

    def unwrap_err(self) -> E:
        return self._message

    def __repr__(self) -> str:
        return f"Err({repr(self._message)})"

Result = Union[Ok[T], Err[str]]

def parse_int(s: str) -> Result[int]:
    try:
        n = int(s)
        return Ok(n)
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def main():
    test_cases = [
        ("10", 2),
        ("10", 0),
        ("abc", 5),
    ]

    for s_val, divisor in test_cases:
        parse_result = parse_int(s_val)

        final_result: Result[int]

        if parse_result.is_err():
            final_result = parse_result
        else:
            num_val = parse_result.unwrap()
            final_result = divide_safe(num_val, divisor)

        if final_result.is_ok():
            print(f"Result: {final_result.unwrap()}")
        else:
            print(f"Error: {final_result.unwrap_err()}")

if __name__ == "__main__":
    main()

