type Tree = Leaf(int) | Node(Tree, int, Tree)

export func tree_sum(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }
}

export func find_max(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => {
      let lmax = find_max(l);
      let rmax = find_max(r);
      if v >= lmax && v >= rmax
      then v
      else if lmax >= rmax
      then lmax
      else rmax
    }
  }
}

export func main() -> () ! {IO} {
  let sample_tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let sum_result = tree_sum(sample_tree);
  let max_result = find_max(sample_tree);

  println("Sum: " ++ show(sum_result));
  println("Max: " ++ show(max_result))
